import net.civeira.phylax.feature.oauth.profile.infrastructure.driver.html.panels.DataExportPanel;
import net.civeira.phylax.feature.oauth.profile.infrastructure.driver.html.panels.MfaPanel;
import net.civeira.phylax.feature.oauth.profile.infrastructure.driver.html.panels.PasskeysPanel;
import net.civeira.phylax.feature.oauth.profile.infrastructure.driver.html.panels.ProfileEditPanel;
import net.civeira.phylax.feature.oauth.profile.infrastructure.driver.html.panels.ProfileViewPanel;
import net.civeira.phylax.feature.oauth.profile.infrastructure.driver.html.panels.RecoveryCodesPanel;
import net.civeira.phylax.feature.oauth.profile.infrastructure.driver.html.panels.SessionsPanel;
import net.civeira.phylax.feature.oauth.session.domain.SessionInfo;
import net.civeira.phylax.feature.oauth.theme.domain.gateway.DecoratePageGateway;

/** The profile pages act only on the account of the session open in the tenant. */
class ProfileHtmlControllerUnitTest {
  private SessionManager sessions;
  private ProfileService profile;
  private UserQueryRepositoryGateway users;
  private DecoratePageGateway decorator;
  private GdprService gdpr;
  private HttpHeaders headers;
  private ProfileHtmlController controller;

  @BeforeEach
  void setUp() {
    sessions = Mockito.mock(SessionManager.class);
    profile = Mockito.mock(ProfileService.class);
    users = Mockito.mock(UserQueryRepositoryGateway.class);
    decorator = Mockito.mock(DecoratePageGateway.class);
    gdpr = Mockito.mock(GdprService.class);
    headers = Mockito.mock(HttpHeaders.class);
    controller = new ProfileHtmlController(sessions, profile, users, decorator,
        Mockito.mock(ProfileViewPanel.class), Mockito.mock(ProfileEditPanel.class),
        Mockito.mock(ChangePasswordPanel.class), Mockito.mock(MfaPanel.class),
        Mockito.mock(SessionsPanel.class), Mockito.mock(MfaRecoveryService.class),
        Mockito.mock(RecoveryCodesPanel.class), Mockito.mock(ScopesConsentGateway.class),
        Mockito.mock(ConsentedScopesPanel.class),
        Mockito.mock(UserAcceptedTermsOfUseQueryRepositoryGateway.class),
        Mockito.mock(TenantTermsOfUseQueryRepositoryGateway.class),
        Mockito.mock(PasskeysPanel.class), gdpr, Mockito.mock(DataExportPanel.class),
        new AccountDeletionPanel());
    AuthenticationData auth = new AuthenticationData();
    auth.setUsername("alice");
    auth.setTenant("acme-uid");
    Mockito.when(sessions.loadSession("cookie", "acme")).thenReturn(Optional
        .of(SessionInfo.builder().userId("alice-uid").issuer("acme").validationData(auth).build()));
  }

  private static ActiveSession active(String id) {
    return new ActiveSession(id, "web", null, null, null, null, null, null);
  }

  private static MultivaluedMap<String, String> form(String... pairs) {
    MultivaluedMap<String, String> form = new MultivaluedHashMap<>();
    for (int i = 0; i < pairs.length; i += 2) {
      form.add(pairs[i], pairs[i + 1]);
    }
    return form;
  }

  private String renderedHtml() {
    ArgumentCaptor<String> html = ArgumentCaptor.forClass(String.class);
    Mockito.verify(decorator).getFullPage(ArgumentMatchers.eq("acme"), ArgumentMatchers.any(),
        html.capture(), ArgumentMatchers.any(Locale.class), ArgumentMatchers.eq("full"));
    return html.getValue();
  }

  @Test
  @DisplayName("Only a session of the same user is revoked, never the current one")
  void revoke_own_sessions_only() {
    Mockito.when(profile.listSessions("alice-uid", "alice"))
        .thenReturn(List.of(active("own"), active("cookie")));

    Assertions.assertEquals(302, controller.revokeSession("acme", "own", "cookie").getStatus());
    controller.revokeSession("acme", "of-another-user", "cookie");
    controller.revokeSession("acme", "cookie", "cookie");

    Mockito.verify(profile).revokeSession("own");
    Mockito.verify(profile, Mockito.never()).revokeSession("of-another-user");
    Mockito.verify(profile, Mockito.never()).revokeSession("cookie");
  }

  @Test
  @DisplayName("A session of another tenant does not act on this one")
  void session_of_another_tenant() {
    Assertions.assertEquals(401, controller.revokeSession("other", "own", "cookie").getStatus());
    Assertions.assertEquals(401,
        controller.renamePasskey("other", "cred", "cookie", form("name", "Phone")).getStatus());
    Mockito.verifyNoInteractions(profile);
  }

  @Test
  @DisplayName("The account is the uid of the session, not a namesake found by name")
  void user_of_the_session() {
    controller.renamePasskey("acme", "cred", "cookie", form("name", "Phone"));

    Mockito.verify(profile).renamePasskey("cred", "alice-uid", "acme", "Phone");
    Mockito.verifyNoInteractions(users);
  }

  @Test
  @DisplayName("Opening the mail link only asks for the confirmation")
  void confirm_link_deletes_nothing() {
    Response response = controller.confirmDeleteAccount("acme", "alice-uid", "the-code", headers);

    Assertions.assertEquals(200, response.getStatus());
    Mockito.verifyNoInteractions(gdpr);
    String html = renderedHtml();
    Assertions.assertTrue(html.contains("method=\"POST\""), html);
    Assertions.assertTrue(html.contains("name=\"uid\" value=\"alice-uid\""), html);
    Assertions.assertTrue(html.contains("name=\"code\" value=\"the-code\""), html);
  }

  @Test
  @DisplayName("The posted confirmation deletes the account when the code is valid")
  void confirm_post_deletes() {
    Mockito.when(gdpr.confirmAccountDeletion("alice-uid", "the-code", "acme")).thenReturn(true);

    Assertions.assertEquals(200,
        controller
            .executeDeleteAccount("acme", form("uid", "alice-uid", "code", "the-code"), headers)
            .getStatus());
    Assertions.assertEquals(400,
        controller.executeDeleteAccount("acme", form("uid", "alice-uid", "code", "wrong"), headers)
            .getStatus());
    Assertions.assertEquals(400,
        controller.executeDeleteAccount("acme", form("uid", "alice-uid"), headers).getStatus());
    Mockito.verify(gdpr).confirmAccountDeletion("alice-uid", "the-code", "acme");
  }
}
